WITH sales_join AS ( SELECT cc.cc_call_center_sk, cc.cc_name, d_sold.d_year, d_sold.d_month_seq, cs.cs_net_profit, d_open.d_date AS open_date, d_close.d_date AS close_date FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN date_dim d_sold ON cs.cs_sold_date_sk = d_sold.d_date_sk LEFT JOIN date_dim d_open ON cc.cc_open_date_sk = d_open.d_date_sk LEFT JOIN date_dim d_close ON cc.cc_closed_date_sk = d_close.d_date_sk ) SELECT cc_call_center_sk AS call_center_sk, cc_name AS call_center_name, d_year AS year, d_month_seq AS month_seq, AVG(cs_net_profit) AS avg_profit, MAX(cs_net_profit) AS max_profit, MIN(cs_net_profit) AS min_profit, CASE WHEN AVG(cs_net_profit) BETWEEN 20000 AND 40000 THEN 'Mid' ELSE 'Other' END AS profit_band, ROW_NUMBER() OVER (PARTITION BY d_year ORDER BY AVG(cs_net_profit) DESC) AS rank_by_avg, MIN(open_date) AS open_date, MAX(close_date) AS close_date FROM sales_join GROUP BY cc_call_center_sk, cc_name, d_year, d_month_seq HAVING MAX(cs_net_profit) > 0 ORDER BY rank_by_avg, year
